ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(Trim(Self.Text)),
    Clear(colEmployeeSearch);
    Set(varSearchText, ""),
    Set(varSearchText, Trim(Self.Text));
    IfError(
        Set(
            varEmpApi,
            'EDS - APIManagement'.Run(
                "employee",
                JSON(
                    {
                        page_size: 10000,
                        page: 1,
                        search_keyword: Trim(Self.Text)
                    }
                ),
                "employeeList"
            )
        );
        ClearCollect(
            colEmployeeSearch,
            ForAll(
                Table(ParseJSON(Coalesce(varEmpApi.response, "{\"value\":[]}"))),
                With(
                    {
                        empId: Text(ThisRecord.Value.employee_id),
                        empName: Text(ThisRecord.Value.full_name),
                        empDept: Text(ThisRecord.Value.department_name),
                        empEmail: Text(ThisRecord.Value.email)
                    },
                    {
                        employee_id: empId,
                        name: empName,
                        department: empDept,
                        email: empEmail,
                        teams_id: "",
                        score: Coalesce(
                            Value(
                                Text(
                                    LookUp(
                                        varCandidates As candidate,
                                        (
                                            !IsBlank(Text(candidate.email))
                                            && Text(candidate.email) = empEmail
                                        )
                                        || (
                                            !IsBlank(Text(candidate.employee_id))
                                            && Text(candidate.employee_id) = empId
                                        ),
                                        Text(candidate.score)
                                    )
                                )
                            ),
                            0
                        )
                    }
                )
            )
        ),
        Clear(colEmployeeSearch);
        Notify("社員検索に失敗しました。もう一度お試しください。", NotificationType.Error)
    )
)

Rules.InvariantScript:
If(
    IsBlank(Trim(Self.Text)),
    Clear(colEmployeeSearch);
    Set(varSearchText, ""),
    Set(varSearchText, Trim(Self.Text));
    Set(
        varEmpApi,
        'EDS-APIManagement1'.Run(
            "employee",
            JSON({page_size:10000, page:1, search_keyword:Trim(Self.Text)}),
            "employeeList"
        )
    );
    ClearCollect(
        colEmployeeSearch,
        ForAll(
            Table(ParseJSON(Substitute(varEmpApi.response, ":null", ":""""")).value) As emp,
            {
                employee_id: Text(emp.Value.employee_id),
                name: Text(emp.Value.full_name),
                department: Text(emp.Value.department_name),
                email: Text(emp.Value.email),
                teams_id: "",
                score: 0
            }
        )
    )
)

If(
    varMatchStep <> 1 || IsBlank(Text(ThisItem.employee_id)),
    false,
    With(
        {
            selectedId: Text(ThisItem.employee_id),
            selectedEmail: Text(ThisItem.email)
        },
        If(
            CountRows(
                Filter(
                    colSelected,
                    (employee_id = selectedId || (!IsBlank(selectedEmail) && email = selectedEmail))
                    && is_cc = false
                )
            ) > 0,
            RemoveIf(
                colSelected,
                (employee_id = selectedId || (!IsBlank(selectedEmail) && email = selectedEmail))
                && is_cc = false
            );
            Set(varSelectedRecipientId, ""),
            RemoveIf(colSelected, is_cc = false);
            Set(varSelectedRecipientId, selectedId);
            Collect(
                colSelected,
                {
                    employee_id: selectedId,
                    name: Text(ThisItem.name),
                    department: Text(ThisItem.department),
                    email: selectedEmail,
                    teams_id: Text(ThisItem.teams_id),
                    score: Coalesce(Value(ThisItem.score), 0),
                    is_cc: false
                }
            );
            Set(varSearchText, "");
            Reset(txtSearch)
        )
    )
)

With(
    {
        selectedId: Text(ThisItem.employee_id),
        selectedEmail: Text(ThisItem.email),
        selectingCc: varMatchStep = 2
    },
    If(
        CountRows(
            Filter(
                colSelected,
                (employee_id = selectedId || (!IsBlank(selectedEmail) && email = selectedEmail))
                && is_cc = selectingCc
            )
        ) = 0,
        If(
            !selectingCc,
            RemoveIf(colSelected, is_cc = false);
            Set(varSelectedRecipientId, selectedId)
        );
        Collect(
            colSelected,
            {
                employee_id: selectedId,
                name: Text(ThisItem.name),
                department: Text(ThisItem.department),
                email: selectedEmail,
                teams_id: Text(ThisItem.teams_id),
                score: Coalesce(Value(ThisItem.score), 0),
                is_cc: selectingCc
            }
        );
        Set(varSearchText, "");
        Reset(txtSearch)
    )
)

With(
    {
        selectedId: Text(ThisItem.employee_id),
        selectedEmail: Text(ThisItem.email),
        selectingCc: varMatchStep = 2
    },
    If(
        CountRows(
            Filter(
                colSelected,
                (employee_id = selectedId || (!IsBlank(selectedEmail) && email = selectedEmail))
                && is_cc = selectingCc
            )
        ) > 0,
        RemoveIf(
            colSelected,
            (employee_id = selectedId || (!IsBlank(selectedEmail) && email = selectedEmail))
            && is_cc = selectingCc
        );
        If(!selectingCc, Set(varSelectedRecipientId, ""))
    )
)

With(
    {
        selectedForStep: Filter(
            colSelected,
            is_cc = (varMatchStep = 2)
            && !IsBlank(employee_id)
        )
    },
    Filter(
        If(
            IsBlank(lblSearchCompact.Text),
            If(
                varMatchStep = 1,
                If(
                    CountRows(selectedForStep) = 0,
                    Filter(
                        varCandidates,
                        !IsBlank(employee_id)
                        || !IsBlank(name)
                        || !IsBlank(email)
                        || !IsBlank(department)
                    ),
                    Ungroup(
                        Table(
                            {
                                data: ForAll(
                                    selectedForStep As selectedEmp,
                                    {
                                        employee_id: Text(selectedEmp.employee_id),
                                        name: Text(selectedEmp.name),
                                        department: Text(selectedEmp.department),
                                        email: Text(selectedEmp.email),
                                        teams_id: Text(selectedEmp.teams_id),
                                        score: Coalesce(selectedEmp.score, 0)
                                    }
                                )
                            },
                            {
                                data: Filter(
                                    varCandidates,
                                    (
                                        !IsBlank(employee_id)
                                        || !IsBlank(name)
                                        || !IsBlank(email)
                                        || !IsBlank(department)
                                    )
                                    && CountRows(
                                        Filter(
                                            selectedForStep,
                                            employee_id = varCandidates[@employee_id]
                                            || (
                                                !IsBlank(varCandidates[@email])
                                                && email = varCandidates[@email]
                                            )
                                        )
                                    ) = 0
                                )
                            }
                        ),
                        data
                    )
                ),
                selectedForStep
            ),
            colEmployeeSearch
        ),
        !IsBlank(employee_id)
        || !IsBlank(name)
        || !IsBlank(email)
        || !IsBlank(department)
    )
)

If(
    IsBlank(Trim(Coalesce(txtDeliverySlip.Text, ""))),
    Set(varSlipRequiredError, true);
    Notify("伝票番号を入力してください", NotificationType.Error),
    Set(varBusy, true);
