        {
            isSharePoint: Lower(Text(LookUp(colHomeQueue, id = Coalesce(varHomeQueueId, varHomeSelectedId)).source)) = "sharepoint",
            remoteUrl: Coalesce(
                LookUp(colHomeQueue, id = Coalesce(varHomeQueueId, varHomeSelectedId)).file_url,
                varImageUrl,
                ""
            ),
            fileBytes: Coalesce(
                If(!IsBlank(varImage) && varImage <> SampleImage, varImage, Blank()),
                LookUp(colHomeQueue, id = Coalesce(varHomeQueueId, varHomeSelectedId)).image,
                If(
                    !IsBlank(imgMatchThumb.Image) && imgMatchThumb.Image <> SampleImage,
                    imgMatchThumb.Image,
                    Blank()
                )
            ),
            saveName: Text(varPackageId) & ".jpg",
            ocrName: If(IsBlank(Trim(Coalesce(varOcrName, ""))), "不明", Trim(varOcrName)),
            ocrDept: If(IsBlank(Trim(Coalesce(varOcrDept, ""))), "不明", Trim(varOcrDept)),
            ocrConf: Coalesce(varOcrConf, 0),
            matchScore: Coalesce(varMatchScore, 0),
            tierVal: Coalesce(varTier, "low"),
            candidatesJson: JSON(varCandidates, JSONFormat.IgnoreBinaryData),
            slipNo: Trim(Coalesce(txtDeliverySlip.Text, varOcrDeliverySlip, "")),
            packageContent: Trim(Coalesce(txtSenderCompany.Text, varOcrSenderInfo, "")),
            senderName: Trim(Coalesce(txtSenderName.Text, varOcrSenderName, "")),
            senderAddress: Trim(Coalesce(txtPackageContents.Text, varOcrSenderDepartment, "")),
            sharepointUrl: If(
                Lower(Text(LookUp(colHomeQueue, id = Coalesce(varHomeQueueId, varHomeSelectedId)).source)) = "sharepoint",
                Coalesce(
                    LookUp(colHomeQueue, id = Coalesce(varHomeQueueId, varHomeSelectedId)).file_url,
                    varImageUrl,
                    ""
                ),
                ""
            ),
            packageDetails: Concat(
                Filter(
                    Table(
                        {
                            label: "伝票番号",
                            value: Trim(Coalesce(txtDeliverySlip.Text, varOcrDeliverySlip, ""))
                        },
                        {
                            label: "荷物内容",
                            value: Trim(Coalesce(txtSenderCompany.Text, varOcrSenderInfo, ""))
                        },
                        {
                            label: "差出人名",
                            value: Trim(Coalesce(txtSenderName.Text, varOcrSenderName, ""))
                        },
                        {
                            label: "差出人部署",
                            value: Trim(Coalesce(txtPackageContents.Text, varOcrSenderDepartment, ""))
                        }
                    ),
                    !IsBlank(value)
                ),
                label & ": " & value,
                Char(10) & Char(10)
            )
        },
        If(
            isSharePoint && IsBlank(remoteUrl),
            Set(varBusy, false);
            Set(varError, "SharePointの画像URLがありません");
            Notify("SharePointの画像URLがありません", NotificationType.Error),

            !isSharePoint && IsBlank(fileBytes),
            Set(varBusy, false);
            Set(varError, "保存する画像がありません");
            Notify("保存する画像がありません", NotificationType.Error),

            IfError(
                Set(
                    varSaveUnknownResult,
                    'EDS-SaveUnknownPackage'.Run(
                        {
                            contentBytes: fileBytes,
                            name: saveName
                        },
                        ocrName,
                        ocrDept,
                        ocrConf,
                        matchScore,
                        tierVal,
                        candidatesJson,
                        Text(varPackageId),
                        slipNo,
                        packageContent,
                        senderName,
                        senderAddress,
                        sharepointUrl
                    )
                );
                Set(varImageUrl, Coalesce(Text(varSaveUnknownResult.image_url), sharepointUrl, remoteUrl));
                ClearCollect(
                    colNotifyPayload,
                    {
                        employee_id: "",
                        package_id: Text(varPackageId),
                        name: "不明",
                        department: "宛先不明！！！！！",
                        email: "",
                        teams_id: "",
                        score: 0,
                        is_cc: false,
                        content_message:
                            If(
                                IsBlank(packageDetails),
                                "新しい、正体不明の小包があります。",
                                "新しい、正体不明の小包があります。" & Char(10) & Char(10) & "詳細:" & Char(10) & Char(10) & packageDetails
                            ),
                        image_url: Coalesce(varImageUrl, ""),
                        slip_no: Trim(Coalesce(txtDeliverySlip.Text, varOcrDeliverySlip, "")),
                        sender_info: Trim(Coalesce(txtSenderCompany.Text, varOcrSenderInfo, "")),
                        sender_address: Trim(Coalesce(txtPackageContents.Text, varOcrSenderDepartment, "")),
                        senderName: Trim(Coalesce(txtSenderName.Text, varOcrSenderName, ""))
                    }
                );
                Set(varNotifyJson, JSON(colNotifyPayload, JSONFormat.IgnoreBinaryData));
                Set(
                    varNotifyResult,
                    'EDS-NotifySelected'.Run(
                        {
                            text_5: varNotifyJson
                        }
                    )
                );
                Set(varBusy, false);
                Refresh(PackageSlipLog);
                Set(varMatchStep, 1);
                Clear(varCandidates);
                Clear(colSelected);
                Set(varTier, "");
                Set(varMatchScore, 0);
                Set(varOcrName, "");
                Set(varOcrDept, "");
                Set(varOcrConf, 0);
                Set(varOcrSenderName, "");
                Set(varOcrSenderInfo, "");
                Set(varOcrDeliverySlip, "");
                Set(varOcrSenderDepartment, "");
                Set(varSelectedRecipientId, "");
                Set(varPackageId, "");
                Set(varFromUnknownList, false);
                If(
                    !IsBlank(varHomeQueueId),
                    RemoveIf(colHomeQueue, id = varHomeQueueId)
                );
                Set(varHomeQueueId, "");
                If(
                    CountRows(colHomeQueue) > 0,
                    With(
                        { nextItem: First(colHomeQueue) },
                        Set(varHomeSelectedId, nextItem.id);
                        Set(varImage, Coalesce(nextItem.image, SampleImage));
                        Set(
                            varImageUrl,
                            If(
                                Text(nextItem.source) = "sharepoint",
                                "",
                                Coalesce(nextItem.file_url, "")
                            )
                        );
                        Set(
                            varImageName,
                            If(
                                !IsBlank(nextItem.path),
                                "SPPATH|" & nextItem.path,
                                Coalesce(nextItem.name, "label.jpg")
                            )
                        )
                    ),
                    Set(varHomeSelectedId, "");
                    Set(varImage, Blank());
                    Set(varImageName, "");
                    Set(varImageUrl, "")
                );
                Set(varProcessedCount, varProcessedCount + 1);
                Set(
                    varShowContinuePopup,
                    varBatchTotal > 0 && CountRows(colHomeQueue) > 0
                );
                Notify("不明荷物として登録しました", NotificationType.Success);
                Navigate(srcHome, ScreenTransition.None),

                Set(varBusy, false);
                Set(varError, "不明登録に失敗しました。もう一度お試しください。");
                Notify(
                    "不明登録に失敗しました: " & Coalesce(FirstError.Message, "もう一度お試しください。"),
                    NotificationType.Error
                )
            )
        )
    )
)

Set(varMatchStep, 1);
Set(varSelectedRecipientId, "");
Set(varPackageId, "");
Set(varHomeQueueId, "");
Set(varFromUnknownList, false);
Clear(varCandidates);
Clear(colSelected);
Set(varTier, "");
Set(varMatchScore, 0);
Set(varOcrName, "");
Set(varOcrDept, "");
Set(varOcrConf, 0);
Set(varOcrSenderName, "");
Set(varOcrSenderInfo, "");
Set(varOcrDeliverySlip, "");
Set(varOcrSenderDepartment, "");
If(
    CountRows(colHomeQueue) > 0,
    With(
        {
            cur: Coalesce(
                LookUp(colHomeQueue, id = varHomeSelectedId),
                First(colHomeQueue)
            )
        },
        Set(varHomeSelectedId, cur.id);
        Set(varImage, Coalesce(cur.image, SampleImage));
        Set(
            varImageUrl,
            If(
                Text(cur.source) = "sharepoint",
                "",
                Coalesce(cur.file_url, "")
            )
        );
        Set(
            varImageName,
            If(
                !IsBlank(cur.path),
                "SPPATH|" & cur.path,
                Coalesce(cur.name, "label.jpg")
            )
        )
    ),
    Set(varHomeSelectedId, "");
    Set(varImage, Blank());
    Set(varImageName, "");
    Set(varImageUrl, "")
);
Navigate(srcHome, ScreenTransition.None)

