ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(Trim(Coalesce(txtDeliverySlip.Text, ""))),
    Set(varSlipRequiredError, true);
    Notify("伝票番号を入力してください", NotificationType.Error),
    !varFromUnknownList && CountRows(Filter(colSelected, is_cc = false && !IsBlank(employee_id))) = 0,
    Notify("受取人を選択してください", NotificationType.Error),
    Set(varBusy, true);
    Set(varError, "");
    Set(varNotifyErrorMessage, "");
    If(IsBlank(varPackageId), Set(varPackageId, Text(GUID())));
    With(
        {
            packageDetails: Concat(
                Filter(
                    Table(
                        {
                            label: "伝票番号",
                            value: Trim(Coalesce(txtDeliverySlip.Text, varOcrDeliverySlip, ""))
                        },
                        {
                            label: "荷物内容",
                            value: Trim(Coalesce(txtSenderCompany.Text, varOcrSenderInfo, ""))
                        },
                        {
                            label: "差出人名",
                            value: Trim(Coalesce(txtSenderName.Text, varOcrSenderName, ""))
                        },
                        {
                            label: "差出人部署",
                            value: Trim(Coalesce(txtPackageContents.Text, varOcrSenderDepartment, ""))
                        }
                    ),
                    !IsBlank(value)
                ),
                label & ": " & value,
                Char(10) & Char(10)
            ),
            absoluteImageUrl: With(
                {
                    siteHost: "https://smartosc0.sharepoint.com",
                    sitePath: "/sites/Teamresponsibleforreceivingexpressshipments",
                    queueRow: LookUp(colHomeQueue, id = Coalesce(varHomeQueueId, varHomeSelectedId))
                },
                With(
                    {
                        raw: Trim(
                            Coalesce(
                                If(Left(Lower(Coalesce(varImageUrl, "")), 4) = "http", varImageUrl, Blank()),
                                If(Left(Lower(Coalesce(queueRow.file_url, "")), 4) = "http", queueRow.file_url, Blank()),
                                queueRow.file_url,
                                queueRow.path,
                                varImageUrl,
                                ""
                            )
                        )
                    },
                    With(
                        {
                            normalized: Substitute(
                                If(
                                    Left(raw, 11) = "/Documents/",
                                    "/Shared Documents/" & Mid(raw, 12, 2000),
                                    Left(raw, 10) = "Documents/",
                                    "/Shared Documents/" & Mid(raw, 11, 2000),
                                    raw
                                ),
                                " ",
                                "%20"
                            )
                        },
                        If(
                            Left(Lower(normalized), 4) = "http",
                            normalized,
                            Left(normalized, 6) = "/sites",
                            siteHost & normalized,
                            !IsBlank(normalized),
                            siteHost & sitePath & If(Left(normalized, 1) = "/", normalized, "/" & normalized),
                            ""
                        )
                    )
                )
            )
        },
        ClearCollect(
            colNotifyPayload,
            ForAll(
                colSelected As selectedEmp,
                {
                    employee_id: Text(selectedEmp.employee_id),
                    package_id: Text(varPackageId),
                    name: Text(selectedEmp.name),
                    department: Text(selectedEmp.department),
                    email: Text(selectedEmp.email),
                    teams_id: Text(selectedEmp.teams_id),
                    score: Coalesce(selectedEmp.score, 0),
                    is_cc: Coalesce(selectedEmp.is_cc, false),
                    slip_no: Trim(Coalesce(txtDeliverySlip.Text, varOcrDeliverySlip, "")),
                    sender_info: Trim(Coalesce(txtSenderCompany.Text, varOcrSenderInfo, "")),
                    sender_name: Trim(Coalesce(txtSenderName.Text, varOcrSenderName, "")),
                    sender_address: Trim(Coalesce(txtPackageContents.Text, varOcrSenderDepartment, "")),
                    content_message:
                        Text(selectedEmp.name) &
                        "（部署: " &
                        Text(selectedEmp.department) &
                        If(
                            IsBlank(packageDetails),
                            "）に新しい荷物があります。",
                            "）に新しい荷物があります。" & Char(10) & Char(10) & "詳細:" & Char(10) & Char(10) & packageDetails
                        ),
                    image_url: Coalesce(absoluteImageUrl, "")
                }
            )
        )
    );
    Set(
        varNotifyJson,
        JSON(colNotifyPayload, JSONFormat.IgnoreBinaryData)
    );
    IfError(
        Set(
            varNotifyResult,
            'EDS-NotifySelected'.Run(
                {
                    text_5: varNotifyJson
                }
            )
        );
        Set(varBusy, false);
        If(
            Lower(Text(Coalesce(varNotifyResult.success, ""))) <> "true",
            Set(varShowNotifyFailed, true),
            Set(varNotifyNavUnknown, varFromUnknownList && !IsBlank(varPackageId));
            If(
                varNotifyNavUnknown,
                Patch(
                    PackageSlipLog,
                    LookUp(PackageSlipLog, PackageId = varPackageId),
                    {
                        IsUnknown: false,
                        Status: {Value: "Resolved"},
                        SelectedRecipientsJson: JSON(colSelected, JSONFormat.IgnoreBinaryData)
                    }
                );
                Refresh(PackageSlipLog)
            );
            Set(varShowNotifySuccess, true)
        ),
        Set(varBusy, false);
        Set(varShowNotifyFailed, true)
    )
)

