                            siteHost & sitePath & If(Left(normalized, 1) = "/", normalized, "/" & normalized),
                            ""
                        )
                    )
                )
            )
        },
        ClearCollect(
            colNotifyPayload,
            ForAll(
                colSelected As selectedEmp,
                {
                    employee_id: Text(selectedEmp.employee_id),
                    package_id: Text(varPackageId),
                    name: Text(selectedEmp.name),
                    department: Text(selectedEmp.department),
                    email: Text(selectedEmp.email),
                    teams_id: Text(selectedEmp.teams_id),
                    score: Coalesce(selectedEmp.score, 0),
                    is_cc: Coalesce(selectedEmp.is_cc, false),
                    slip_no: Trim(Coalesce(txtDeliverySlip.Text, varOcrDeliverySlip, "")),
                    sender_info: Trim(Coalesce(txtSenderCompany.Text, varOcrSenderInfo, "")),
                    sender_name: Trim(Coalesce(txtSenderName.Text, varOcrSenderName, "")),
                    sender_address: Trim(Coalesce(txtPackageContents.Text, varOcrSenderDepartment, "")),
                    content_message:
                        Text(selectedEmp.name) &
                        "（部署: " &
                        Text(selectedEmp.department) &
                        If(
                            IsBlank(packageDetails),
                            "）に新しい荷物があります。",
                            "）に新しい荷物があります。" & Char(10) & Char(10) & "詳細:" & Char(10) & Char(10) & packageDetails
                        ),
                    image_url: Coalesce(absoluteImageUrl, "")
                }
            )
        )
    );
    Set(
        varNotifyJson,
        JSON(colNotifyPayload, JSONFormat.IgnoreBinaryData)
    );
    IfError(
        Set(
            varNotifyResult,
            'EDS-NotifySelected'.Run(
                {
                    text_5: varNotifyJson
                }
            )
        );
        Set(varBusy, false);
        If(
            Lower(Text(Coalesce(varNotifyResult.success, ""))) <> "true",
            Set(varShowNotifyFailed, true),
            Set(varNotifyNavUnknown, varFromUnknownList && !IsBlank(varPackageId));
            If(
                varNotifyNavUnknown,
                Patch(
                    PackageSlipLog,
                    LookUp(PackageSlipLog, PackageId = varPackageId),
                    {
                        IsUnknown: false,
                        Status: {Value: "Resolved"},
                        SelectedRecipientsJson: JSON(colSelected, JSONFormat.IgnoreBinaryData)
                    }
                );
                Refresh(PackageSlipLog)
            );
            Set(varShowNotifySuccess, true)
        ),
        Set(varBusy, false);
        Set(varShowNotifyFailed, true)
    )
)

